CREATE FUNCTION pg_temp.seed_id(n bigint) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$
    SELECT ('019a0000-0000-7000-8000-' || lpad(n::text, 12, '0'))::uuid
$$;

